"""Render the discussion plan and its maintained notation registry; no inference."""
from html import escape as e
import hashlib,json
from pathlib import Path
from build_project_progress import document,bullets
ROOT=Path(__file__).resolve().parents[1];D=ROOT/'research/what-to-think'
def read(name):return json.loads((D/name).read_text())
def m(tex):return r'\('+e(tex)+r'\)'
def eq(tex):return '<div class="equation">'+r'\['+e(tex)+r'\]'+'</div>'
MATH=r'''<script>window.MathJax={tex:{inlineMath:[['\\(','\\)']],displayMath:[['\\[','\\]']]},svg:{fontCache:'global'}};</script><script id="MathJax-script" async src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-svg.js"></script>'''
CSS='''.equation{max-width:100%;overflow-x:auto;margin:1rem 0;padding:1rem;border-radius:9px;background:var(--surface-2)}.equation mjx-container[display="true"]{margin:0!important}mjx-container{max-width:100%}.plan-list li{margin:.65rem 0}.plan-note{border-left:4px solid var(--accent);padding:.7rem 1rem;background:var(--accent-soft)}.chunk-demo{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.5rem;margin:1rem 0}.chunk-demo>div{padding:.8rem;border:1px solid var(--border);border-radius:8px}.plan-table{font-size:.92rem}.plan-table th{min-width:7rem}.plan-table td{overflow-wrap:anywhere}.plan-table mjx-container{font-size:95%!important}.notation-table td:first-child{min-width:12rem}.token-legend{font-size:.9rem;color:var(--muted)}@media(max-width:700px){.chunk-demo{grid-template-columns:1fr}.plan-table{font-size:.88rem}}'''
class Tables:
 def __init__(self):self.n=0
 def __call__(self,caption,headers,rows,extra=''):
  self.n+=1;key='plan-table-'+str(self.n)
  return '<p class="asset-label table-caption" id="'+key+'">Table '+str(self.n)+'. '+e(caption)+'<span class="table-scroll-hint">Scroll sideways on a narrow screen.</span></p><div class="table-wrap" tabindex="0" role="region" aria-labelledby="'+key+'"><table class="plan-table '+extra+'" aria-labelledby="'+key+'"><thead><tr>'+''.join('<th scope="col">'+e(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def ul(items):return '<ul class="plan-list">'+''.join('<li>'+e(x)+'</li>' for x in items)+'</ul>'
def finish(name,title,body):
 text=document(name,title,'todo',body)
 text=text.replace('</head>','<style>'+CSS+'</style>'+MATH+'</head>')
 (ROOT/name).write_text(text)
def main():
 manifest={f.name:hashlib.sha256(f.read_bytes()).hexdigest() for f in D.iterdir() if f.is_file() and f.name!='manifest.json'}
 (D/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
 p=read('plan.json');registry=read('models.json');notation=read('notation.json');prompts=read('prompts.json');results=read('results-template.json');lit=read('literature.json');t=Tables()
 body='<header class="hero"><span class="eyebrow">Plan for discussion · no new inference</span><h1>What to think</h1></header><section class="section" id="summary"><h2>The plan in six sentences</h2>'+bullets([dict(text=x) for x in p['summary']])+'<p><a href="todo.html">Project TODO</a> · <a href="notation.html">Notation table</a> · <a href="daily-log.html">Daily log</a> · <a href="#results">Empty results tables</a></p></section>'
 body+='<section class="section" id="scope"><h2>Evaluation set and reference answers</h2><p>Use all 105 distinct questions: 93 AMI questions over 24 meetings and 12 earnings-call questions over two calls. Every question has an existing recording and a draft reference answer. The earlier twenty-question review is starting evidence; this plan does not certify all 105 references. Keep alternatives under their original question.</p>'+ul(p['gold_steps'])+'<p><strong>Gate before evaluation:</strong> freeze 105 verified text answers and required-fact checklists. Reference-answer speech remains deferred. Prompt and chunk tuning use additional meetings outside this exposed evaluation bank.</p><p><a href="research/what-to-think/answer-validation-template.json">All 105 reference-audit records</a> · <a href="experiments/question-overview.html">Existing question statistics</a></p></section>'
 body+='<section class="section" id="chunking"><h2>Use shared chunks with enough speech</h2><p>Small S1 audio frames stay model-specific. The larger pre-thinking chunks are shared across text and audio conditions.</p>'+ul([p['chunking'][key] for key in ['rule','fillers','cap_rule','low_activity','request','common_schedule','causality','same_content']])
 body+='<figure><div class="chunk-demo"><div>0–3 s: “um”</div><div>3–8 s: acknowledgement</div><div>8–26 s: promise and constraint</div><div>26–26.5 s: observed pause</div></div><figcaption>Figure 1. Illustrative grouping: these small units become one useful chunk, rather than four separate private calls; this is not a measured source alignment.</figcaption></figure><p>'+e(p['chunking']['development'])+' '+e(p['chunking']['not_when_study'])+'</p></section>'
 body+='<section class="section" id="notation"><h2>Separate time, instructions and results</h2><p>'+e(notation['convention'])+' The actual user question is part of the input at request time; it is hidden from all earlier private calls.</p>'
 short=[notation['symbols'][i] for i in [3,4,5,6,7,8,9,11,13,14,15,16]]
 body+=t('Core notation; the full maintained registry also defines acoustic tokens, references and accounting.',['Symbol','Meaning'],[[m(x['tex']),e(x['name']+'. '+x['definition'])] for x in short])
 body+='<p>The original use of '+m('z')+' for both an index and a result is resolved: '+m('i')+' is the integer index and '+m('z_i')+' is the generated private result. The generic answer-format instruction '+m(r'q^{\mathrm{ans}}')+' is shared across conditions and omitted from the formulas below.</p><p><a href="notation.html">Open the full notation table</a> · <a href="research/what-to-think/notation.json">Machine-readable registry</a></p></section>'
 body+='<section class="section" id="conditions"><h2>The experiment families</h2><p>A reactive S2 baseline runs only after the actual request. A pre-thinking variant has two parts: earlier private updates and a final request-time answer.</p>'
 body+=eq(r'\begin{aligned}z_i&\sim p_{\theta_m}\!\bigl(z_i\mid D_{e,i},\\&\qquad Z_{<i},Q_{\le i}^{(g)}\bigr),\\&\qquad t_i<S_e.\end{aligned}')
 body+='<p>Here '+m('D_{e,i}')+' is the available GT transcript, generated transcript or audio prefix. Collect only those earlier results in '+m('Z_e^{-}')+'; the unfinished meeting tail and complete request are added to the final input.</p>'
 body+=t('Core families, each evaluated on the same 105 questions. T3 and T4 repeat for each transcript tool; the common final-answer instruction is suppressed.',['ID','Input and earlier work','Request-time distribution','Output'],[
 ['S1','Native audio only; S2 disabled.',m(r'p_{\theta_m}(R_e\mid x^{(m)}_{1:J_{m,e}})'),'Speech and native text where available.'],
 ['T1','GT transcript; no earlier private calls.',m(r'p_{\theta_m}(h_e,r_e\mid Y_{\le T_e})'),'Native thinking, if exposed, and answer text.'],
 ['T2','GT transcript plus earlier results and chosen private goals.',m(r'p_{\theta_m}(h_e,r_e\mid Y_{\le T_e},Z_e^{-},Q^{(g)})'),'Same output fields as T1.'],
 ['T3(v)','Generated speaker-attributed transcript; no earlier private calls.',m(r'p_{\theta_m}(h_e,r_e\mid\widehat Y^{(v)}_{\le T_e})'),'Same output fields as T1.'],
 ['T4(v)','Generated transcript plus earlier results and chosen private goals.',m(r'p_{\theta_m}(h_e,r_e\mid\widehat Y^{(v)}_{\le T_e},Z_e^{-},Q^{(g)})'),'Same output fields as T1.'],
 ['A1','Audio prefix with the spoken request; no earlier private calls.',m(r'p_{\theta_m}(h_e,r_e\mid A_{e,\le T_e})'),'Audio-grounded thinking and text answer.'],
 ['A2','Audio prefix plus earlier private results and chosen goals.',m(r'p_{\theta_m}(h_e,r_e\mid A_{e,\le T_e},Z_e^{-},Q^{(g)})'),'Same output fields as A1.']])
 body+='<p>For T2/T4 the update equation uses the matching transcript prefix; for A2 it uses the matching audio prefix. For a model without a native thinking channel, the output is only '+m('r_e')+'; omit '+m('h_e')+' from the joint expression. These equations describe inference behavior, not a new training loss or a measured log-likelihood. Supplying earlier results does not make them correct by definition.</p>'+ul(p['protocol'])+'</section>'
 body+='<section class="section" id="models"><h2>Model and transcript-tool candidates</h2><p>Checked against primary model cards and papers on 27 October 2026. These are local candidates for qualification, not a claim of new performance on this evaluation set; revisions, modes, precision and decoding must be frozen before runs.</p>'
 body+=t('Primary model candidates; text-only describes the experimental input, even when a checkpoint can accept other modalities.',['Group','Model','Why include it?','Native thinking status'],[[e(x['group']),'<a href="'+e(x['source'],quote=True)+'">'+e(x['name'])+'</a>',e(x['reason']),e(x['thinking'].replace('_',' '))] for x in registry['models']])
 body+=t('Two generated-transcript pipelines; speaker clusters and their revisions remain tool-generated.',['ID','Pipeline','Use and causal rule'],[[x['id'],'<a href="'+x['sources'][0]+'">'+e(x['name'])+'</a> · <a href="'+x['sources'][1]+'">diarizer</a>',e(x['reason']+' '+x['causality'])] for x in registry['transcript_tools']])
 body+='<p>Nemotron 3 supports eight speakers; the older four-speaker Sortformer is not the default for earnings calls. Prefix-only pyannote/WhisperX recomputation is an offline content condition, not evidence of real-time streaming. Never attach GT names to generated speaker clusters in model inputs.</p><details><summary>Newer or alternative models considered</summary>'+ul([x['name']+': '+x['decision'] for x in registry['reviewed_reserves']])+'<p>Gemma 4 31B is retained for text; the audio-capable 12B card limits audio to thirty seconds, so it is not substituted into a full-history audio comparison.</p></details></section>'
 body+='<section class="section" id="prompts"><h2>Select the private goals on development data</h2><p>The best prompt is not known yet. Start with the following source-grounded alternatives, choose separately for each model and modality, and freeze before the all-105 evaluation.</p>'+t('Draft private-work goals; no evaluation question or answer is supplied.',['ID','Goal','Work requested'],[[x['id'],e(x['name']),e(x['goal'])] for x in prompts['families']])+'<p>'+e(prompts['selection'])+'</p><details><summary>Draft instructions, outputs and controls</summary><p>'+e(prompts['shared_instruction'])+'</p><p><strong>For text:</strong> '+e(prompts['text_rule'])+'</p><p><strong>For audio:</strong> '+e(prompts['audio_rule'])+'</p><p><strong>Shared final-answer instruction:</strong> '+e(prompts['final_answer_instruction'])+'</p><p>'+e(prompts['prior_results_format'])+'</p><p>Combined-goal artifacts can contain facts, person/task links, checked implications, open items and source references; the summary control remains a summary rather than being forced into all these jobs.</p>'+ul(prompts['ablations'])+'<p>The main four-family comparison tests the whole pre-thinking method; a goal-only-at-request control separates improved prompting from reuse of earlier work. An example useful result is that B owns a promised consultation with Melissa and Jean, while the rule remains unresolved; another is a conditional 4:2:1 priority ratio from two twice-as-important relations.</p></details></section>'
 body+='<section class="section" id="metrics"><h2>Accuracy and thinking tokens for the request</h2>'+ul(p['metrics'])
 body+=eq(r'\begin{aligned}\mathrm{Acc}_{105}&=\frac{1}{105}\sum_{e=1}^{105}a_e,\\N_e^{\mathrm{think}}&=\left|\operatorname{Tok}_m(h_e)\right|.\end{aligned}')
 body+=eq(r'\begin{aligned}N_e^{\mathrm{pre}}&=\sum_{i:t_i<S_e}\left|\operatorname{Tok}_m(z_i)\right|,\\N_e^{\mathrm{req,out}}&=N_e^{\mathrm{think}}+N_e^{\mathrm{ans}}\\&\quad+N_e^{\mathrm{aux}}+N_e^{\mathrm{ctrl}}.\end{aligned}')
 body+='<p>Use recorded generated token IDs; flag retokenized counts as approximate. The token sum applies when a native thinking channel is observable; otherwise its numerical value is N/A and the recorded total output count is reported directly. Earlier results read at request time are input tokens, even when they contain old reasoning. Acoustic codes and S1 Inner Monologue text are not relabeled as native thinking tokens.</p><p>Use paired outcomes and per-meeting summaries. Include partial-fact precision/recall and unsupported claims as diagnostics; compare request-time token reductions at comparable accuracy, with tokenizer and truncation status visible.</p></section>'
 body+='<section class="section" id="capacity"><h2>Retain full history, then use a declared fallback</h2>'+ul(p['capacity'])+eq(r'(D_e^{B},Z_e^{B})=\mathcal S_B(D_e,Z_e^{-})')+'<p>Use the selected conditioning variables in a budgeted row; keep its mode distinct from full history and native rolling context.</p><p>The latest question is about 47.06 minutes into its source recording, so advertised short-clip support cannot establish full-prefix capacity. A fallback can be useful, but it must remain visible as a budgeted-history condition.</p></section>'
 body+='<section class="section" id="results"><h2>Results to fill after the plan is agreed</h2><p><strong>No new results are entered.</strong> The selected matrix has '+str(results['planned_cells'])+' cells × 105 questions = '+str(results['planned_final_responses'])+' planned final answers; this excludes intermediate private calls, reference work, prompt search, judges and optional controls. Four text families become six cells per model because T3/T4 each use two transcript tools; g* denotes the goal selected on development data.</p>'
 for group,label in [('S1','S1-only'),('text','Text-only S2'),('speech','Speech-LLM S2')]:
  rr=[x for x in results['rows'] if x['group']==group]
  body+=t(label+' result template. Dashes are unfilled measurements, not zero scores.',['Model','Family / tool','Planned questions','Correct / 105','Request thinking tokens','Request output tokens','Pre-thinking tokens','Context mode'],[[e(x['model']),x['family']+(' / '+x['tool'] if x['tool'] not in ['none','GT'] else '')+(' / g*' if x['method']=='prethinking' else ''),'105','—','N/A: no native channel' if x['thinking_observability'].startswith('not_applicable') else '—','—','—','To record'] for x in rr])
 body+='<p><a href="research/what-to-think/results-template.csv">CSV template</a> · <a href="research/what-to-think/results-template.json">JSON template</a></p></section>'
 body+='<section class="section" id="appendix"><h2>Appendix</h2><details id="resources"><summary>Resource plan and execution order</summary><p>'+e(p['resources']['current_dependencies'])+' Current GPU count and maximum active GPU count are both zero.</p>'+t('Future allocation envelopes, not measured capacity results. Jobs are sequential; maximum four GPUs active.',['Job / stage','GPU count, type and VRAM','Roles, sharing and dependencies'],[[e(x['name']),e(x['resources'].split(';')[0]),e(x['resources']+' Qualify inputs and reference facts before evaluation.')] for x in registry['models']]+[[x['id']+' transcript tool','1 L40S 48 GB',e(x['resources']+' Run before T3/T4; outputs are reused across models.') ] for x in registry['transcript_tools']]+[['Reference proposal / validation','1 or 2 H100 80 GB','Qwen draft/check worker alone on GPU 0 or independent Gemma review TP2 on GPUs 0–1, sequential; Codex source inspection uses zero GPUs.'],['Answer judging','1 or 2 H100 80 GB','Use a different family where possible; judge alone on GPU 0 or TP2 across 0–1 after answer generation.']])+ul(p['resources'][key] for key in ['policy','qualification'])+'<ol>'+''.join('<li>'+e(x)+'</li>' for x in p['execution_order'])+'</ol></details><details id="literature"><summary>Nine verified papers and why they matter</summary>'+t('Primary-source literature; proposed thresholds and new evaluation results are not established by these papers.',['Paper','Relevant method','Use here'],[['<a href="'+x['url']+'">'+e(x['title'])+'</a><p>'+e(x['authors']+', '+str(x['year']))+'</p>',e(x['method']),e(x['relevance'])] for x in lit['papers']])+'</details><p><a href="research/what-to-think/plan.json">Plan data</a> · <a href="research/what-to-think/prompts.json">Draft prompt families</a> · <a href="research/what-to-think/models.json">Candidate registry</a> · <a href="research/what-to-think/literature.json">Checked sources</a> · <a href="research/what-to-think/manifest.json">File hashes</a></p></section>'
 finish('what-to-think.html','What to think: experiment plan',body)
 nt=Tables();body='<header class="hero"><h1>Notation table</h1></header><section class="section"><ul><li>Use these symbols consistently in the plan, prompts and future result files.</li><li>Keep native audio frames, private-work chunks, user requests and reasoning results separate.</li></ul><p><a href="what-to-think.html">Experiment plan</a> · <a href="todo.html">Project TODO</a> · <a href="research/what-to-think/notation.json">Registry JSON</a></p>'+nt('Notation version '+notation['version']+', maintained with the experiment plan.',['Symbol','Name','Definition'],[[m(x['tex']),e(x['name']),e(x['definition'])] for x in notation['symbols']],extra='notation-table')+'</section>'
 finish('notation.html','Notation table',body)
 print('Rendered what-to-think plan and maintained notation page; all result cells remain empty.')
if __name__=='__main__':main()
